#!/usr/bin/env node
// KTX2 (Basis Universal) copy of a character GLB for the engine (checkpoint-1 §2 item 8):
//   node web/tools/ktx2.mjs IN.glb OUT.glb [--uastc-quality 2] [--etc1s-quality 128]
// UASTC (quality 2, Zstandard) for normals, ORM / roughness / occlusion, clearcoat and anisotropy maps;
// ETC1S (quality 128, sRGB transfer) for base colour and sheen colour; mipmaps generated by the
// encoder. Blender cannot import KTX2, so the PNG GLB stays the build's source of truth and this writes
// a separate file (export.ktx2 names it character.ktx2.glb). Encoder: ktx2-encoder (basis_universal
// WASM, no toktx needed); glTF I/O: @gltf-transform/core. Writes only OUT.
import { readFile, writeFile } from 'node:fs/promises';
import { NodeIO, VertexLayout } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { ktx2 } from 'ktx2-encoder/gltf-transform';
import { PNG } from 'pngjs';

const argv = process.argv.slice(2);
const [src, dst] = argv.filter((a) => !a.startsWith('--') && !/^\d+$/.test(a));
const opt = (n, d) => {
  const i = argv.indexOf(`--${n}`);
  return i >= 0 ? Number(argv[i + 1]) : d;
};
if (!src || !dst) {
  console.error('usage: ktx2.mjs IN.glb OUT.glb [--uastc-quality 2] [--etc1s-quality 128]');
  process.exit(2);
}
const uastcQ = opt('uastc-quality', 2);
const etc1sQ = opt('etc1s-quality', 128);

// LDR images are decoded here (the encoder needs RGBA rows in Node); JPEG does not occur in our GLBs
async function imageDecoder(buf) {
  const png = PNG.sync.read(Buffer.from(buf));
  return { width: png.width, height: png.height, data: new Uint8Array(png.data.buffer, png.data.byteOffset, png.data.length) };
}

const t0 = Date.now();
// separate vertex streams, as Blender writes them (gltf-transform defaults to interleaved)
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).setVertexLayout(VertexLayout.SEPARATE);
const doc = await io.readBinary(new Uint8Array(await readFile(src)));
const before = doc.getRoot().listTextures().reduce((n, t) => n + (t.getImage()?.byteLength ?? 0), 0);
// the WASM encoder caps a texture at ~12 Mpix: halve anything larger (the 4k head maps -> 2k; at the
// portrait's ~600 px head a 2k map is still above 1 texel per pixel)
const MAX_TEXELS = 12582912;
const halved = [];
for (const t of doc.getRoot().listTextures()) {
  if (t.getMimeType() !== 'image/png') continue;
  let png = PNG.sync.read(Buffer.from(t.getImage()));
  if (png.width * png.height <= MAX_TEXELS) continue;
  const from = [png.width, png.height];
  while (png.width * png.height > MAX_TEXELS) {
    const w = png.width >> 1;
    const h = png.height >> 1;
    const out = new PNG({ width: w, height: h });
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        for (let c = 0; c < 4; c++) {
          const a = (i, j) => png.data[((2 * y + j) * png.width + 2 * x + i) * 4 + c];
          out.data[(y * w + x) * 4 + c] = (a(0, 0) + a(1, 0) + a(0, 1) + a(1, 1) + 2) >> 2;
        }
      }
    }
    png = out;
  }
  t.setImage(new Uint8Array(PNG.sync.write(png)));
  halved.push({ name: t.getName(), from, to: [png.width, png.height] });
}
const common = { generateMipmap: true, imageDecoder };
// data maps must say linear: ktx2-encoder's defaults tag every file sRGB (isSetKTX2SRGBTransferFunc: true),
// and three then linearises roughness / normals on sampling (wet skin, broken eyes in the first test)
const data = { ...common, isUASTC: true, uastcLDRQualityLevel: uastcQ, needSupercompression: true, isSetKTX2SRGBTransferFunc: false, isInputSRGB: false, isPerceptual: false };
await doc.transform(
  ktx2({ ...data, isNormalMap: true, slots: /^normalTexture$/ }),
  ktx2({ ...data, slots: /(occlusion|metallicRoughness|clearcoat|clearcoatRoughness|anisotropy)Texture$/ }),
  ktx2({ ...common, isUASTC: false, qualityLevel: etc1sQ, isSetKTX2SRGBTransferFunc: true, slots: /^(baseColor|sheenColor|emissive)Texture$/ }),
);
const texs = doc.getRoot().listTextures();
const after = texs.reduce((n, t) => n + (t.getImage()?.byteLength ?? 0), 0);
const left = texs.filter((t) => t.getMimeType() !== 'image/ktx2').map((t) => t.getName());
await writeFile(dst, await io.writeBinary(doc));
console.log(JSON.stringify({ in: src, out: dst, textures: texs.length, png_left: left, halved, image_mb_before: +(before / 1e6).toFixed(1), image_mb_after: +(after / 1e6).toFixed(1), uastc_quality: uastcQ, etc1s_quality: etc1sQ, seconds: Math.round((Date.now() - t0) / 1000) }));
